public sealed class ProfileConstants {

	public static byte[] kProfileMagic = new byte[] { 'p', 'r', 'o', '\0' };

	public static int kProfileMagicLength = kProfileMagic.length;

	public static byte[] kProfileVersion_008 = new byte[] { '0', '0', '8', '\0' };
	public static byte[] kProfileVersion_009 = new byte[] { '0', '0', '9', '\0' };
	/**
	 * Android 10
	 * Android 11
	 */
	public static byte[] kProfileVersion_010 = new byte[] { '0', '1', '0', '\0' };

